import React from 'react';
import { useNavigate } from 'react-router-dom';

function LandingPage() {
  const navigate = useNavigate();

  return (
    <div className="landing-outer">
      <div className="container">
        <h1>AI Ad Generator</h1>
        <p>
          Instantly create cinematic, story-driven, and creative ads for your company.
          Powered by the latest AI and inspired by the best ads in history.
        </p>
        <button className="cta-button" onClick={() => navigate('/chat')}>
          Start Generating Ads
        </button>
      </div>
    </div>
  );
}

export default LandingPage;
